<template>
<div class="page narrow"><header class="page-head"><div><h1>UX Scenario Agent</h1><p>Analyze your PRD and turn user scenarios into review-ready wireframes.</p></div><RouterLink class="ghost-btn" to="/history">History</RouterLink></header>
<section class="card input-card"><div class="section-title"><span class="step">1</span><div><h2>Provide PRD</h2><p>Upload a Markdown/text PRD or paste it below.</p></div></div><label class="upload"><input type="file" accept=".md,.txt,text/markdown,text/plain" @change="onFile"/><div class="upload-icon">↥</div><b>{{ fileName || 'Choose PRD File' }}</b><span>.md or .txt · max 5 MB</span></label><div class="or"><span>or</span></div><textarea v-model="prd" placeholder="Paste your PRD here..."></textarea></section>
<section class="card"><div class="section-title"><span class="step">2</span><div><h2>What would you like to analyze?</h2><p>Select one or more UX perspectives.</p></div><button class="link-btn" @click="toggleAll">{{ allSelected?'Clear all':'Select all' }}</button></div><div class="perspectives"><label v-for="p in perspectives" :key="p.id" class="perspective" :class="{selected:selected.includes(p.id)}"><input type="checkbox" v-model="selected" :value="p.id"/><span class="check">✓</span><div><b>{{p.label}}</b><small>{{p.description}}</small></div></label></div><button class="primary full" :disabled="!selected.length || !prd.trim()" @click="generate">Generate Analysis <span>→</span></button><p v-if="error" class="error">{{error}}</p></section></div>
</template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';const router=useRouter();const prd=ref('');const fileName=ref('');const selected=ref(['concept','user-scenario','structures','interaction-policy','ux-design-scope','open-decisions']);const error=ref('');const perspectives=[{id:'concept',label:'Concept',description:'Product purpose and UX intent'},{id:'user-scenario',label:'User Scenario',description:'Users, goals and journeys'},{id:'structures',label:'Structures',description:'Information architecture and screens'},{id:'interaction-policy',label:'Interaction & Policy',description:'Interactions, states and rules'},{id:'ux-design-scope',label:'UX Design Scope',description:'Design work and deliverables'},{id:'open-decisions',label:'Open Decisions & Dependencies',description:'Missing info, risks and dependencies'}];const allSelected=computed(()=>selected.value.length===perspectives.length);function toggleAll(){selected.value=allSelected.value?[]:perspectives.map(x=>x.id)}async function onFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!/\.(md|txt)$/i.test(f.name)){error.value='Please choose a .md or .txt file.';return}fileName.value=f.name;prd.value=await f.text()}async function generate(){error.value='';try{const fd=new FormData();fd.append('prd',prd.value);fd.append('fileName',fileName.value||'PRD.md');fd.append('perspectives',JSON.stringify(selected.value));const r=await api.create(fd);router.push(`/analysis/${r.id}`)}catch(e){error.value=e instanceof Error?e.message:'Unable to start analysis.'}}</script>
